const retainedAttachments = `-- name: RetainedAttachments :many
SELECT a.id FROM custom_form_attachments a JOIN custom_form_sessions s ON s.id = a.session_id
WHERE s.form_id = $1::integer AND s.user_id IS NOT DISTINCT FROM $2::integer AND a.field_key = $3::text
  AND a.id = ANY($4::uuid[]) AND a.claimed_at IS NOT NULL
`

type RetainedAttachmentsParams struct {
	FormID   int32         `json:"form_id"`
	UserID   *int32        `json:"user_id"`
	FieldKey string        `json:"field_key"`
	Ids      []pgtype.UUID `json:"ids"`
}

func (q *Queries) RetainedAttachments(ctx context.Context, arg RetainedAttachmentsParams) ([]pgtype.UUID, error) {
	rows, err := q.db.Query(ctx, retainedAttachments,
		arg.FormID,
		arg.UserID,
		arg.FieldKey,
		arg.Ids,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []pgtype.UUID{}
	for rows.Next() {
		var id pgtype.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

